from pathlib import Path
import json
p=Path(__file__).parent
def e(k,t,tag='span',cls=''):return f'<{tag} data-edit="{k}" class="{cls}">{t}</{tag}>'
def foot(n):return '<footer>'+e('disclaimer','虚构计划／暂无实测结果')+f'<span>{n}</span></footer>'
def photo(asset,view,caption):
 config=json.loads((p/'asset-config.json').read_text()) if (p/'asset-config.json').exists() else {}
 kind=config.get(asset,{}).get('sourceKind','pending');identity='AI生成概念图，非现场记录。' if kind=='ai-generated' else '图像待接入，未完成视觉验收。'
 return f'<figure class="photo {view}"><div class="image-window" data-view="{view}" data-asset="{asset}"><img src="assets/{asset.lower()}.png" alt="图{asset}：{identity}"></div><figcaption>'+e('caption-'+view,caption)+f'<strong class="asset-identity" data-identity="{asset}">{identity}</strong></figcaption></figure>'
